// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

/** A member of staff a supervisor may question in a mock interview, or name as an action's owner (user_id). */
export interface InterviewStaffOut {
  employee_id: number;
  emp_number: string;
  full_name: string;
  designation: string;
  department_name: string | null;
  /** Their login; null for staff without one (they can still be questioned, not own an action) */
  user_id: number | null;
  roles: string[];
  last_mock_at: string | null;
  /** The caller: nobody examines themselves */
  is_me: boolean;
}

/** The questions to put in a mock interview: the member of staff's weak points first. */
export interface MockInterviewPlanOut {
  lang: "en" | "ur";
  employee: MockEmployeeOut;
  role: string;
  role_name: string;
  questions: MockPlanQuestionOut[];
}

export interface MockEmployeeOut {
  employee_id: number;
  emp_number: string;
  full_name: string;
  designation: string;
  department_name: string | null;
  /** Their login, when they have one (their rehearsals inform the plan) */
  user_id: number | null;
}

export interface MockPlanQuestionOut {
  /** I-<indicator>-<requirement>, e.g. I-055-ii; C-041-a (Clinic), IIC-060-a (II C) */
  key: string;
  /** The language of the texts: the one asked for, else the caller's preference */
  lang: "en" | "ur";
  /** The manual the question comes from: I (2024), or Clinic / IIC for the questions of those manuals whose indicator has no Category I question; served only to an establishment of that category */
  framework: "I" | "Clinic" | "IIC";
  /** The indicator in its framework's manual (Category I: the 2024 revision) */
  indicator: number;
  /** The establishment's recorded PHC category (I until recorded) */
  category: "Clinic" | "IIC" | "IIB" | "IIA" | "I";
  /** The indicator's number(s) in that category's manual; empty when the category's manual has no equivalent */
  indicators_in_category: number[];
  area: string;
  /** The chapter's name in the language of the texts */
  area_name: string;
  /** A short label of the indicator in Haspataal's words (English) */
  indicator_label: string;
  /** Category I only: Mandatory = red banner in the manual, Operational = yellow; null for a question of another framework (its grade says it) */
  phc_type: "Mandatory" | "Operational" | null;
  /** Red: full compliance (Mandatory in Category I); Yellow: at least 80 % (Operational) */
  grade: "Red" | "Yellow";
  /** The compliance requirement's number in the indicator's Assessment table */
  requirement: string;
  /** As the PHC's manual words it (English) */
  requirement_text: string;
  /** The Evidence column of that row */
  evidence: ("Observation" | "Interview" | "Document Review")[];
  /** True: the manual's evidence is not Interview, but surveyors commonly ask it */
  beyond_filter: boolean;
  /** The role codes that rehearse it; all_staff = every member of staff */
  roles: string[];
  /** Whom the surveyor would usually ask (English) */
  ask: string;
  /** In the language of the texts */
  question: string;
  /** The hospital adapted the answer or the key points to its SOP (in any language) */
  adapted: boolean;
  /** False: the hospital marked it as not applicable here */
  applicable: boolean;
  not_applicable_reason: string | null;
  /** The caller's latest self-rating */
  my_rating: "Knew" | "Partly" | "DidNotKnow" | null;
  /** When the caller should rehearse it next */
  my_next_due: string | null;
  /** Why it was picked: missed at the last mock interview, not known when rehearsed, never rehearsed (mandatory first) */
  reason: string;
}

/** A mock interview as the PHC's surveyor would hold it: the questions put to one member of staff and each answer. */
export interface MockInterviewIn {
  /** The member of staff questioned (with or without a login) */
  employee_id: number;
  /** The role whose questions were put (GET /msds/interview-prep/roles) */
  role: string;
  /** Default: now */
  held_at?: string | null;
  note?: string | null;
  items: MockInterviewItemIn[];
}

export interface MockInterviewItemIn {
  /** A question's key from GET /msds/interview-prep/questions */
  question_key: string;
  /** Judged against the question's key points */
  result: "Met" | "PartlyMet" | "NotMet";
  /** Required unless Met: what was missing or wrong */
  note?: string | null;
  /** A corrective action when the answer showed a gap in PRACTICE (the SOP is not followed, the equipment is missing), not only in knowledge; only with PartlyMet or NotMet */
  action?: QualityActionIn | null;
}

/** A corrective or preventive action for its source (a record review, an incident). */
export interface QualityActionIn {
  action_type: "Corrective" | "Preventive";
  description: string;
  /** Who carries it out; they are notified and close it with the evidence (GET /staff/lookup → user_id; GET /quality/record-review/people, GET /facility/staff) */
  owner_user_id: number;
  due_date: string;
  /** The department (GET /admin/departments) */
  department_id?: number | null;
}

export interface MockInterviewOut {
  mock_interview_id: number;
  interview_number: string;
  employee_id: number;
  employee_name: string;
  emp_number: string;
  role_code: string;
  role_name: string | null;
  examiner_user_id: number;
  examiner_name: string;
  held_at: string;
  note: string | null;
  questions: number;
  met: number;
  partly_met: number;
  not_met: number;
  /** Met counts 1, PartlyMet half, as a percentage of the questions */
  score_pct: number;
  /** The language of the items' questions */
  lang: "en" | "ur";
  items: MockInterviewItemOut[];
  actions: MockActionOut[];
}

export interface MockInterviewItemOut {
  item_id: number;
  question_key: string;
  question: string;
  framework: "I" | "Clinic" | "IIC";
  indicator: number;
  /** Category I only: Mandatory = red banner in the manual, Operational = yellow; null for a question of another framework (its grade says it) */
  phc_type: "Mandatory" | "Operational" | null;
  grade: "Red" | "Yellow";
  result: "Met" | "PartlyMet" | "NotMet";
  note: string | null;
}

/** A corrective action the mock interview raised (the action register, GET /quality/actions). */
export interface MockActionOut {
  action_id: number;
  action_number: string;
  action_type: "Corrective" | "Preventive";
  description: string;
  owner_name: string;
  due_date: string;
  status: "Open" | "Done" | "Cancelled";
}

export interface MockInterviewSummaryOut {
  mock_interview_id: number;
  interview_number: string;
  employee_id: number;
  employee_name: string;
  emp_number: string;
  role_code: string;
  role_name: string | null;
  examiner_user_id: number;
  examiner_name: string;
  held_at: string;
  note: string | null;
  questions: number;
  met: number;
  partly_met: number;
  not_met: number;
  /** Met counts 1, PartlyMet half, as a percentage of the questions */
  score_pct: number;
}

export interface InterviewRoleOut {
  /** A role code: the deck, the pocket guide and the mock interviews are per role */
  role: string;
  name: string;
  /** The questions this role rehearses for the establishment's recorded category, its own and the ones for all staff */
  questions: number;
  /** Of those, the ones written for this role (not for all staff) */
  own_questions: number;
  /** Of those, the ones of red indicators (Mandatory in Category I) */
  mandatory: number;
  /** The caller holds this role */
  mine: boolean;
}

/** One question with everything needed to rehearse it, in the language of the texts. */
export interface InterviewQuestionDetailOut {
  /** I-<indicator>-<requirement>, e.g. I-055-ii; C-041-a (Clinic), IIC-060-a (II C) */
  key: string;
  /** The language of the texts: the one asked for, else the caller's preference */
  lang: "en" | "ur";
  /** The manual the question comes from: I (2024), or Clinic / IIC for the questions of those manuals whose indicator has no Category I question; served only to an establishment of that category */
  framework: "I" | "Clinic" | "IIC";
  /** The indicator in its framework's manual (Category I: the 2024 revision) */
  indicator: number;
  /** The establishment's recorded PHC category (I until recorded) */
  category: "Clinic" | "IIC" | "IIB" | "IIA" | "I";
  /** The indicator's number(s) in that category's manual; empty when the category's manual has no equivalent */
  indicators_in_category: number[];
  area: string;
  /** The chapter's name in the language of the texts */
  area_name: string;
  /** A short label of the indicator in Haspataal's words (English) */
  indicator_label: string;
  /** Category I only: Mandatory = red banner in the manual, Operational = yellow; null for a question of another framework (its grade says it) */
  phc_type: "Mandatory" | "Operational" | null;
  /** Red: full compliance (Mandatory in Category I); Yellow: at least 80 % (Operational) */
  grade: "Red" | "Yellow";
  /** The compliance requirement's number in the indicator's Assessment table */
  requirement: string;
  /** As the PHC's manual words it (English) */
  requirement_text: string;
  /** The Evidence column of that row */
  evidence: ("Observation" | "Interview" | "Document Review")[];
  /** True: the manual's evidence is not Interview, but surveyors commonly ask it */
  beyond_filter: boolean;
  /** The role codes that rehearse it; all_staff = every member of staff */
  roles: string[];
  /** Whom the surveyor would usually ask (English) */
  ask: string;
  /** In the language of the texts */
  question: string;
  /** The hospital adapted the answer or the key points to its SOP (in any language) */
  adapted: boolean;
  /** False: the hospital marked it as not applicable here */
  applicable: boolean;
  not_applicable_reason: string | null;
  /** The caller's latest self-rating */
  my_rating: "Knew" | "Partly" | "DidNotKnow" | null;
  /** When the caller should rehearse it next */
  my_next_due: string | null;
  /** The question in English, as an English-speaking surveyor may put it */
  question_en: string;
  /** rtl for Urdu: lay the texts out right to left */
  direction: "ltr" | "rtl";
  /** Original (English); Draft: a translation not yet reviewed by a native speaker with clinical knowledge (show it as a draft); Reviewed */
  text_status: "Original" | "Draft" | "Reviewed";
  /** Other ways the surveyor may ask the same thing */
  variants: string[];
  /** The answer to rehearse, with the hospital's facts filled in */
  model_answer: string;
  /** Hospital: adapted to the hospital's SOP in this language */
  answer_source: "Standard" | "Hospital";
  /** The bank's answer in this language with its {{placeholders}} (to adapt it) */
  standard_answer: string;
  /** What a good answer covers: the self-check and the mock interview checklist */
  key_points: string[];
  standard_key_points: string[];
  /** What the surveyor may ask next */
  follow_ups: string[];
  /** Answers that lose the point */
  pitfalls: string[];
  /** What to show the surveyor */
  show_me: string[];
  references: string[];
  facts: InterviewFactOut[];
  documents: InterviewDocumentOut[];
  /** Show under every answer: a key point not true on the ward is a gap to report */
  notice: string;
  /** The languages the hospital adapted the answer in; one of two: check the other says the same */
  adapted_languages: ("en" | "ur")[];
  hospital_version: HospitalAnswerOut | null;
}

/** A fact of the hospital the answer quotes, read live from a setting or the records. */
export interface InterviewFactOut {
  key: string;
  label: string;
  /** Null: not set yet (the answer shows a bracketed prompt instead) */
  value: string | null;
  set: boolean;
  /** Where the hospital sets it */
  where: string;
}

export interface InterviewDocumentOut {
  key: string;
  title: string;
  /** The inspection document that evidences the indicator (GET, needs its permission) */
  pdf_url: string;
}

/** The hospital's version (msds_interview_answers): null fields fall back to the bank's text in that language. */
export interface HospitalAnswerOut {
  /** English */
  model_answer: string | null;
  /** English */
  key_points: string[] | null;
  /** Urdu */
  model_answer_ur: string | null;
  /** Urdu */
  key_points_ur: string[] | null;
  /** For every language */
  applicable: boolean;
  not_applicable_reason: string | null;
  note: string | null;
  updated_by_name: string;
  updated_at: string;
  row_version: number;
}

/** A corrective or preventive action of the hospital's register (MSDS IMS 162, CQI 83, 107). */
export interface QualityActionOut {
  action_id: number;
  action_number: string;
  /** What found the need: a medical record review, an incident, a complaint, an infection control audit, a committee meeting, a mock drill, a mock PHC interview, a QA round, a patient's feedback */
  source: "RecordReview" | "Incident" | "Complaint" | "InfectionAudit" | "Meeting" | "Drill" | "MockInterview" | "QaRound" | "PatientFeedback";
  cycle_id: number | null;
  cycle_number: string | null;
  incident_id: number | null;
  incident_number: string | null;
  complaint_id: number | null;
  complaint_number: string | null;
  ipc_audit_id: number | null;
  audit_number: string | null;
  meeting_id: number | null;
  meeting_number: string | null;
  drill_id: number | null;
  drill_number: string | null;
  mock_interview_id: number | null;
  /** The mock PHC interview that found the gap (MIV-...) */
  interview_number: string | null;
  qa_round_id: number | null;
  /** The in-charge's QA round whose finding it addresses (QAR-...) */
  qa_round_number: string | null;
  feedback_id: number | null;
  /** The patient feedback it answers (FB-...) */
  feedback_number: string | null;
  /** The number of the review cycle, the incident, the complaint, the audit or the meeting */
  source_number: string;
  action_type: "Corrective" | "Preventive";
  description: string;
  /** A record review: the checklist item whose deficiencies it addresses */
  criterion_code: string | null;
  department_id: number | null;
  department_name: string | null;
  owner_user_id: number;
  owner_name: string;
  due_date: string;
  status: "Open" | "Done" | "Cancelled";
  /** Done: what was done (the evidence); Cancelled: why it was dropped */
  outcome_note: string | null;
  completed_at: string | null;
  completed_by_name: string | null;
  created_by: number;
  created_by_name: string;
  created_at: string;
  row_version: number;
  is_overdue: boolean;
}

export interface DepartmentOut {
  department_id: number;
  code: string;
  name: string;
  is_clinical: boolean;
  is_active: boolean;
  row_version: number;
}

/** The staff to question in a mock interview (with or without a login) — GET /api/v1/msds/interview-prep/staff (who may call: holders of msds.interview.conduct). */
export function staffMsdsInterviewPrep(query?: { role?: string | null; search?: string | null; limit?: number }): Promise<InterviewStaffOut[]> {
  return api<InterviewStaffOut[]>("GET", withQuery(`/msds/interview-prep/staff`, query), undefined);
}

/** The questions to put in a mock interview: the member of staff's weak points first — GET /api/v1/msds/interview-prep/mock-interviews/plan (who may call: holders of msds.interview.conduct). */
export function plan(query: { employee_id: number; role: string; count?: number; lang?: "en" | "ur" | null }): Promise<MockInterviewPlanOut> {
  return api<MockInterviewPlanOut>("GET", withQuery(`/msds/interview-prep/mock-interviews/plan`, query), undefined);
}

/** Record a mock PHC interview: each answer Met, PartlyMet or NotMet, and the actions for the gaps — POST /api/v1/msds/interview-prep/mock-interviews (who may call: holders of msds.interview.conduct). */
export function recordMock(body: MockInterviewIn): Promise<MockInterviewOut> {
  return api<MockInterviewOut>("POST", `/msds/interview-prep/mock-interviews`, body, { idempotent: true });
}

/** Mock interviews, newest first (staff who do not conduct them see their own) — GET /api/v1/msds/interview-prep/mock-interviews (who may call: holders of msds.interview.practice or msds.interview.conduct or msds.interview.manage). */
export function listMocks(query?: { employee_id?: number | null; role?: string | null; limit?: number }): Promise<MockInterviewSummaryOut[]> {
  return api<MockInterviewSummaryOut[]>("GET", withQuery(`/msds/interview-prep/mock-interviews`, query), undefined);
}

/** One mock interview: each answer and the actions it raised — GET /api/v1/msds/interview-prep/mock-interviews/{mock_interview_id} (who may call: holders of msds.interview.practice or msds.interview.conduct or msds.interview.manage). */
export function getMock(mock_interview_id: number, query?: { lang?: "en" | "ur" | null }): Promise<MockInterviewOut> {
  return api<MockInterviewOut>("GET", withQuery(`/msds/interview-prep/mock-interviews/${mock_interview_id}`, query), undefined);
}

/** The roles and how many inspection interview questions each rehearses — GET /api/v1/msds/interview-prep/roles (who may call: holders of msds.interview.practice or msds.interview.conduct or msds.interview.manage). */
export function rolesMsdsInterviewPrep(): Promise<InterviewRoleOut[]> {
  return api<InterviewRoleOut[]>("GET", `/msds/interview-prep/roles`, undefined);
}

/** One question: other ways of asking, the model answer with the hospital's facts, key points, follow-ups, pitfalls, what to show — GET /api/v1/msds/interview-prep/questions/{key} (who may call: holders of msds.interview.practice or msds.interview.conduct or msds.interview.manage). */
export function getQuestion(key: string, query?: { lang?: "en" | "ur" | null }): Promise<InterviewQuestionDetailOut> {
  return api<InterviewQuestionDetailOut>("GET", withQuery(`/msds/interview-prep/questions/${key}`, query), undefined);
}

/** The action register (mine: the actions I own) — GET /api/v1/quality/actions (who may call: any logged-in user: the actions they own (mine is forced without quality.action.view or quality.action.manage)). */
export function listActions(query?: { source?: "RecordReview" | "Incident" | "Complaint" | "InfectionAudit" | "Meeting" | "Drill" | "MockInterview" | "QaRound" | "PatientFeedback" | null; status?: "Open" | "Done" | "Cancelled" | null; mine?: boolean; overdue_only?: boolean; department_id?: number | null; limit?: number }): Promise<QualityActionOut[]> {
  return api<QualityActionOut[]>("GET", withQuery(`/quality/actions`, query), undefined);
}

/** Departments — GET /api/v1/admin/departments (who may call: any logged-in user). */
export function departments(): Promise<DepartmentOut[]> {
  return api<DepartmentOut[]>("GET", `/admin/departments`, undefined);
}
